-- Minimal inspected production schema, 2026-10-27. Test database only.
create table public.profiles(id uuid primary key, role text not null default 'user', account_type text not null default 'standard', is_verified boolean not null default false, is_verified_merchant boolean not null default false, is_banned boolean not null default false, city text, district text, display_name text, username text, avatar_url text);
create table public.businesses(id uuid primary key default gen_random_uuid(),owner_id uuid references profiles(id),name text not null,city text,district text,moderation_status text not null default 'approved');
create table public.services(id uuid primary key default gen_random_uuid(),provider_id uuid references profiles(id),name text not null,business_id uuid references businesses(id),city text,district text,moderation_status text not null default 'approved');
create table public.business_hours(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,day_of_week smallint not null check(day_of_week between 0 and 6),opens_at time,closes_at time,is_closed boolean not null default false,created_at timestamptz not null default now(),constraint business_hours_business_id_day_of_week_key unique(business_id,day_of_week),constraint business_hours_check check((is_closed and opens_at is null and closes_at is null)or(not is_closed and opens_at is not null and closes_at is not null and opens_at<>closes_at)));
create table public.reviews(id uuid primary key default gen_random_uuid(),reviewer_id uuid not null references profiles(id) on delete cascade,business_id uuid references businesses(id) on delete cascade,service_id uuid references services(id) on delete cascade,rating integer not null check(rating between 1 and 5),body text,created_at timestamptz not null default now(),constraint review_target check((business_id is not null)<>(service_id is not null)));
create table public.events(id uuid primary key default gen_random_uuid(),organizer_id uuid not null references profiles(id) on delete cascade,title text not null,description text not null default '',city text not null,district text,starts_at timestamptz not null,ends_at timestamptz,location_name text,latitude double precision,longitude double precision,cover_url text,status text not null default 'published' check(status in('published','cancelled','ended')),created_at timestamptz not null default now(),moderation_status text not null default 'approved',category text,date_label text,attendees_count integer not null default 0,is_free boolean not null default true,agenda jsonb not null default '[]',guidelines text);
create table public.event_attendees(event_id uuid not null references events(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,status text not null default 'going' check(status in('going','interested','cancelled')),created_at timestamptz not null default now(),primary key(event_id,user_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),request_id uuid,created_at timestamptz not null default now(),created_by uuid references profiles(id));
create table public.conversation_members(conversation_id uuid references conversations(id),user_id uuid references profiles(id),joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations(id),sender_id uuid not null references profiles(id),body text not null,created_at timestamptz not null default now(),edited_at timestamptz,read_by uuid[] not null default '{}');
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),type text not null,title text not null,body text,data jsonb not null default '{}',read_at timestamptz,created_at timestamptz not null default now(),target_type text,target_id uuid);
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references profiles(id),target_type text not null,target_id uuid not null,reason text not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.banned_words(word text primary key,enabled boolean not null default true);
create table public.admin_activity_logs(id uuid primary key default gen_random_uuid(),actor_id uuid,action text,target_type text,target_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
-- Test-only permissions model. Real production RPC belongs to the permission migration.
create table public.commerce_test_permissions(user_id uuid,permission text,primary key(user_id,permission));
create function public.hayna_has_permission(p_permission text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.commerce_test_permissions where user_id=auth.uid() and permission=p_permission)$$;
grant usage on schema public to anon,authenticated,service_role;
grant select on public.profiles,public.businesses,public.services to anon,authenticated;
